-- =====================================================================
-- MF MPanel Evidence - Supabase Production Database Schema
-- Run this in your Supabase SQL Editor to make your database and admin
-- panel 100% compatible with the Android Application.
-- =====================================================================

-- 1. Enable UUID extension if not already enabled
create extension if not exists "uuid-ossp";

-- 2. Pairing Codes table (Generated by Admin Panel, redeemed by Android App)
create table if not exists public.pairing_codes (
    id uuid default gen_random_uuid() primary key,
    code text not null unique,
    email text not null,
    is_used boolean default false not null,
    used_by text,
    used_at timestamp with time zone,
    created_at timestamp with time zone default timezone('utc'::text, now()) not null,
    expires_at timestamp with time zone default timezone('utc'::text, now() + interval '24 hours')
);

-- 3. App Registrations table (Tracks activated Android devices per officer)
create table if not exists public.app_registrations (
    id uuid default gen_random_uuid() primary key,
    user_id text not null unique,
    email text not null,
    status text default 'ACTIVATED' not null, -- 'ACTIVATED', 'WAITING_CONFIRMATION', 'ACCESS_REVOKED'
    pairing_code text,
    team_id text default 'Evidence Team Alpha',
    device_info text,
    created_at timestamp with time zone default timezone('utc'::text, now()) not null,
    updated_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 4. Config table (Stores export settings, zip password, admin preferences)
create table if not exists public.config (
    id uuid default gen_random_uuid() primary key,
    key text not null unique,
    value jsonb not null,
    updated_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Insert default export settings with zip password if not exists
insert into public.config (key, value)
values ('export_settings', '{"zip_password": "MF-Evidence-Secure-2026!"}'::jsonb)
on conflict (key) do nothing;

-- 5. Evidence Batches & Submissions sync tables
create table if not exists public.evidence_batches (
    id text primary key,
    user_id text not null,
    email text not null,
    title text,
    item_count int default 0,
    created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

create table if not exists public.evidence_items (
    id text primary key,
    batch_id text references public.evidence_batches(id) on delete cascade,
    platform text,
    url text,
    screenshot_path text,
    html_path text,
    metadata jsonb,
    created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 6. Enable Row Level Security (RLS) on tables
alter table public.pairing_codes enable row level security;
alter table public.app_registrations enable row level security;
alter table public.config enable row level security;
alter table public.evidence_batches enable row level security;
alter table public.evidence_items enable row level security;

-- 7. Create open policies for anonymous/authenticated access via anon key (matching Android client needs)
create policy "Allow public read/write on pairing_codes" on public.pairing_codes for all using (true) with check (true);
create policy "Allow public read/write on app_registrations" on public.app_registrations for all using (true) with check (true);
create policy "Allow public read on config" on public.config for select using (true);
create policy "Allow public read/write on evidence_batches" on public.evidence_batches for all using (true) with check (true);
create policy "Allow public read/write on evidence_items" on public.evidence_items for all using (true) with check (true);

-- 8. Create indexes for high performance queries
create index if not exists idx_pairing_codes_code on public.pairing_codes(code);
create index if not exists idx_app_registrations_user_id on public.app_registrations(user_id);
create index if not exists idx_app_registrations_email on public.app_registrations(email);
